#include "exercise.h"
#include <ctype.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static void add(char **s, size_t *n, const char *t, size_t k) {
    *s = (char *)realloc(*s, *n + k + 1);
    memcpy(*s + *n, t, k);
    *n += k;
    (*s)[*n] = 0;
}
static void literal(char **s, size_t *n, const char *t) { add(s, n, t, strlen(t)); }
static void inline_text(char **out, size_t *n, const char *p, size_t len) {
    for (size_t i = 0; i < len;) {
        if (p[i] == '_') {
            size_t width = i + 1 < len && p[i + 1] == '_' ? 2 : 1, end = i + width;
            while (end + width <= len) {
                if (p[end] == '_' && (width == 1 || p[end + 1] == '_'))
                    break;
                end++;
            }
            if (end + width <= len) {
                literal(out, n, width == 2 ? "<strong>" : "<em>");
                inline_text(out, n, p + i + width, end - i - width);
                literal(out, n, width == 2 ? "</strong>" : "</em>");
                i = end + width;
                continue;
            }
        }
        add(out, n, p + i, 1);
        i++;
    }
}
char *parse(const char *t) {
    char *out = (char *)calloc(1, 1);
    size_t n = 0;
    bool list = false;
    for (;;) {
        size_t len = strcspn(t, "\n"), prefix = 0;
        int heading = 0;
        while (prefix < len && t[prefix] == '#')
            prefix++;
        if (prefix >= 1 && prefix <= 6 && prefix < len && t[prefix] == ' ')
            heading = (int)prefix;
        bool item = len >= 2 && t[0] == '*' && t[1] == ' ';
        if (!item && list) {
            literal(&out, &n, "</ul>");
            list = false;
        }
        char tag[16];
        if (item) {
            if (!list) {
                literal(&out, &n, "<ul>");
                list = true;
            }
            strcpy(tag, "li");
            prefix = 2;
        } else if (heading) {
            snprintf(tag, 16, "h%d", heading);
            prefix++;
        } else {
            strcpy(tag, "p");
            prefix = 0;
        }
        literal(&out, &n, "<");
        literal(&out, &n, tag);
        literal(&out, &n, ">");
        inline_text(&out, &n, t + prefix, len - prefix);
        literal(&out, &n, "</");
        literal(&out, &n, tag);
        literal(&out, &n, ">");
        t += len;
        if (!*t)
            break;
        t++;
    }
    if (list)
        literal(&out, &n, "</ul>");
    return out;
}

